-- Lab 3.4 - generate the small-file problem.
--   docker compose exec -T trino trino -f /work/day3/lab_3_4_microbatches.sql
--
-- 500 INSERTs, each one a separate Iceberg COMMIT, so each writes its own data file
-- AND its own manifest. This is what a streaming upsert or a per-minute micro-batch
-- does to a table over a day, compressed into a couple of minutes.

CREATE SCHEMA IF NOT EXISTS iceberg.silver;
DROP TABLE IF EXISTS iceberg.silver.trips_micro;
CREATE TABLE iceberg.silver.trips_micro (
  trip_id    integer,
  pu_zone_id integer,
  fare       double,
  dt         date
);

